                let must_attack: Vec<ObjectId> = eligible.iter()
                    .filter(|&&id| {
                        state.has_continuous_effect(id, &|e| {
                            match e {
                                crate::types::ContinuousEffect::ForceAttack { scope } => Some(scope),
                                _ => None,
                            }
                        }, registry)
                    })
                    .copied()
                    .collect();
