                    castable_spells: vec![],
                }
            }
            AwaitingAction::ResolutionChoice { choice, .. } => {
                use crate::state::ResolutionChoiceKind;
                use crate::actions::ResolvedChoice;
                let actions = match choice {
                    ResolutionChoiceKind::PayOrNot { .. } => {
